import React from "react";
import Icon from "../../../components/AppIcon";

const HeroSection = ({ searchQuery, onSearchChange }) => {
  return (
    <section className="bg-gradient-to-br from-primary/10 to-accent/10 py-16 lg:py-20">
      <div className="max-w-4xl mx-auto px-4 lg:px-6 text-center">
        <h1 className="font-heading font-bold text-4xl lg:text-5xl text-foreground mb-6">
          School Library
        </h1>
        <p className="font-body text-lg lg:text-xl text-muted-foreground mb-8 max-w-3xl mx-auto leading-relaxed">
          Discover inspiring stories, insights, and updates from GS Des Parents
          community members. Explore topics on youth empowerment, technology,
          leadership, and community development.
        </p>

        {/* Search Bar */}
        <div className="relative max-w-xl mx-auto">
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Icon name="Search" size={20} className="text-muted-foreground" />
            </div>
            <input
              type="text"
              placeholder="Search articles, topics, or tags..."
              value={searchQuery}
              onChange={(e) => onSearchChange?.(e?.target?.value)}
              className="block w-full pl-10 pr-4 py-3 border border-input bg-card rounded-lg font-body placeholder:text-muted-foreground focus:ring-2 focus:ring-ring focus:border-transparent transition-smooth shadow-card"
            />
          </div>

          {/* Search suggestions */}
          {searchQuery && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-card rounded-lg border border-border shadow-elevated z-10">
              <div className="p-2">
                <p className="text-sm text-muted-foreground px-2 py-1">
                  Searching for "{searchQuery}"...
                </p>
              </div>
            </div>
          )}
        </div>


      </div>
    </section>
  );
};

export default HeroSection;
