import React, { useState, useEffect } from "react";
import axios from "axios";
import Icon from "../../components/AppIcon";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";
import Footer from "../../components/ui/Footer";
import DocumentViewer from "../../components/DocumentViewer";

const Documents = () => {
  const [viewerOpen, setViewerOpen] = useState(false);
  const [viewerUrl, setViewerUrl] = useState("");
  const [viewerName, setViewerName] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("all");
  const [sortBy, setSortBy] = useState("date");
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [downloading, setDownloading] = useState({});

  // Document categories matching your Mongoose model
  const categories = [
    { id: "all", name: "All Documents", icon: "FileText", color: "text-gray-600" },
    { id: "administrative", name: "Administrative", icon: "ClipboardList", color: "text-blue-600" },
    { id: "academic", name: "Academic", icon: "BookOpen", color: "text-purple-600" },
    { id: "financial", name: "Financial", icon: "CreditCard", color: "text-green-600" },
    { id: "announcement", name: "Announcements", icon: "Megaphone", color: "text-orange-600" },
    { id: "other", name: "Other", icon: "Folder", color: "text-gray-500" },
  ];

  // File type icons mapping
  const fileTypeIcons = {
    PDF: "FileText",
    DOC: "FileEdit",
    DOCX: "FileEdit",
    XLS: "FileSpreadsheet",
    XLSX: "FileSpreadsheet",
    PPT: "Presentation",
    PPTX: "Presentation",
    TXT: "FileText",
    ZIP: "Archive"
  };

  // Fetch documents from API
  useEffect(() => {
    const fetchDocuments = async () => {
      try {
        setLoading(true);
        const response = await axios.get("https://new-school-web-90vd.onrender.com/document/select/all");
        
        // Handle different response structures
        let documentsData = [];
        if (Array.isArray(response.data)) {
          documentsData = response.data;
        } else if (response.data && Array.isArray(response.data.documents)) {
          documentsData = response.data.documents;
        } else if (response.data && Array.isArray(response.data.data)) {
          documentsData = response.data.data;
        } else {
          console.warn("Unexpected API response structure:", response.data);
        }
        
        // Transform documents to ensure they have required fields
        const transformedDocuments = documentsData.map(doc => ({
          _id: doc._id || doc.id,
          name: doc.name || "Untitled Document",
          category: doc.category || "other",
          description: doc.description || "No description available",
          fileSize: doc.fileSize || "N/A",
          fileType: doc.fileType || "FILE",
          uploadDate: doc.uploadDate || doc.createdAt || new Date().toISOString(),
          url: doc.url || "",
          downloads: doc.downloads || 0
        }));
        
        setDocuments(transformedDocuments);
        setError(null);
      } catch (err) {
        console.error("Error fetching documents:", err);
        setError("Failed to load documents. Please try again later.");
        setDocuments([]);
      } finally {
        setLoading(false);
      }
    };

    fetchDocuments();
  }, []);

  // Filter documents based on search and category
  const filteredDocuments = documents.filter((doc) => {
    const matchesSearch =
      doc.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      doc.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory =
      selectedCategory === "all" || doc.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  // Sort documents
  const sortedDocuments = [...filteredDocuments].sort((a, b) => {
    switch (sortBy) {
      case "name":
        return a.name.localeCompare(b.name);
      case "date":
        return new Date(b.uploadDate) - new Date(a.uploadDate);
      case "size":
        const sizeA = parseFloat(a.fileSize) || 0;
        const sizeB = parseFloat(b.fileSize) || 0;
        return sizeB - sizeA;
      case "downloads":
        return (b.downloads || 0) - (a.downloads || 0);
      default:
        return new Date(b.uploadDate) - new Date(a.uploadDate);
    }
  });

  // Get category color
  const getCategoryColor = (categoryId) => {
    const category = categories.find(cat => cat.id === categoryId);
    return category ? category.color : "text-gray-600";
  };

  // Get file type icon
  const getFileTypeIcon = (fileType) => {
    return fileTypeIcons[fileType] || "File";
  };

  const handleView = (doc) => {
    if (!doc._id) {
      console.error("Document ID is missing");
      alert("Cannot preview this document");
      return;
    }

    // Use direct URL if available, otherwise use download endpoint
    const url = doc.url 
      ? (doc.url.startsWith('http') 
          ? doc.url 
          : `${window.location.origin}${doc.url}`)
      : `https://new-school-web-90vd.onrender.com/document/download/${doc._id}`;
    
    setViewerUrl(url);
    setViewerName(doc.name);
    setViewerOpen(true);
  };

  const handleDownload = async (doc) => {
    if (!doc._id) {
      console.error("Document ID is missing");
      alert("Cannot download this document");
      return;
    }

    // Set downloading state for this document
    setDownloading(prev => ({ ...prev, [doc._id]: true }));

    try {
      const response = await axios({
        url: `https://new-school-web-90vd.onrender.com/document/download/${doc._id}`,
        method: 'GET',
        responseType: 'blob',
        headers: {
          'Accept': '*/*'
        }
      });

      // Get filename from response headers or use document name
      const contentDisposition = response.headers['content-disposition'];
      let filename = doc.name;
      
      if (contentDisposition) {
        const filenameMatch = contentDisposition.match(/filename="?(.+)"?/);
        if (filenameMatch && filenameMatch[1]) {
          filename = filenameMatch[1];
        }
      }

      // Ensure filename has extension
      if (!filename.toLowerCase().endsWith(`.${doc.fileType.toLowerCase()}`)) {
        filename = `${filename}.${doc.fileType.toLowerCase()}`;
      }

      // Create blob URL and trigger download
      const blob = new Blob([response.data], { 
        type: response.headers['content-type'] || 'application/octet-stream' 
      });
      const blobUrl = window.URL.createObjectURL(blob);
      
      // Use the global document object
      const link = window.document.createElement('a');
      link.href = blobUrl;
      link.download = filename;
      window.document.body.appendChild(link);
      link.click();
      
      // Cleanup
      window.document.body.removeChild(link);
      window.URL.revokeObjectURL(blobUrl);

      // Show success message
      alert(`"${doc.name}" has been downloaded successfully!`);

      // Update downloads count locally
      setDocuments(prevDocs => 
        prevDocs.map(document => 
          document._id === doc._id 
            ? { ...document, downloads: (document.downloads || 0) + 1 }
            : document
        )
      );

    } catch (error) {
      console.error('Download error:', error);
      
      // Try fallback to direct URL if download endpoint fails
      if (doc.url) {
        try {
          const fallbackUrl = doc.url.startsWith('http') 
            ? doc.url 
            : `${window.location.origin}${doc.url}`;
          
          const link = window.document.createElement('a');
          link.href = fallbackUrl;
          link.download = doc.name;
          link.target = '_blank';
          window.document.body.appendChild(link);
          link.click();
          window.document.body.removeChild(link);
        } catch (fallbackError) {
          console.error('Fallback download also failed:', fallbackError);
          alert('Failed to download document. Please try again later.');
        }
      } else {
        alert('Failed to download document. Please try again later.');
      }
    } finally {
      // Reset downloading state
      setDownloading(prev => ({ ...prev, [doc._id]: false }));
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    } catch (e) {
      return "Invalid Date";
    }
  };

  const formatFileSize = (size) => {
    if (!size || size === "N/A") return "N/A";
    return size;
  };

  // Get category count
  const getCategoryCount = (categoryId) => {
    return documents.filter((doc) => doc.category === categoryId).length;
  };

  return (
    <>
      <Helmet>
        <title>Documents Library - GS DES PARENTS</title>
        <meta
          name="description"
          content="Access and download important school documents, forms, policies, and resources from GS DES PARENTS."
        />
        <meta
          name="keywords"
          content="documents, forms, policies, academic calendar, handbook, GS DES PARENTS, school resources"
        />
        <meta property="og:title" content="Documents Library - GS DES PARENTS" />
        <meta
          property="og:description"
          content="Access and download important school documents and resources"
        />
        <meta property="og:type" content="website" />
        <meta name="twitter:card" content="summary_large_image" />
        <link rel="canonical" href="/documents" />
      </Helmet>

      <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white">
        {/* Header */}
        <PublicHeader />

        {/* Main Content */}
        <main className="pt-16">
          {/* Hero Section with Gradient */}
          <section className="relative py-16 lg:py-20 bg-gradient-to-r from-blue-600 via-purple-600 to-indigo-600">
            <div className="absolute inset-0 bg-black/10" />
            <div className="relative max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h1 className="font-heading font-bold text-4xl lg:text-5xl text-white mb-4 drop-shadow-lg">
                  Document Library
                </h1>
                <p className="font-body text-lg text-blue-100 max-w-3xl mx-auto">
                  Access and download important school documents, forms, policies, and resources.
                  All documents are organized by category for easy navigation.
                </p>
              </div>

              {/* Search and Filter Bar */}
              <div className="max-w-5xl mx-auto">
                <div className="bg-white/95 backdrop-blur-sm border border-white/20 rounded-2xl p-6 shadow-2xl">
                  <div className="flex flex-col lg:flex-row gap-4">
                    {/* Search Input */}
                    <div className="flex-1">
                      <div className="relative">
                        <Icon
                          name="Search"
                          size={20}
                          className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                        />
                        <input
                          type="text"
                          placeholder="Search documents by name or description..."
                          value={searchTerm}
                          onChange={(e) => setSearchTerm(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent shadow-sm"
                        />
                      </div>
                    </div>

                    {/* Category Filter */}
                    <div className="lg:w-48">
                      <div className="relative">
                        <Icon
                          name="Filter"
                          size={18}
                          className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 z-10"
                        />
                        <select
                          value={selectedCategory}
                          onChange={(e) => setSelectedCategory(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent appearance-none shadow-sm"
                        >
                          {categories.map((category) => (
                            <option key={category.id} value={category.id}>
                              {category.name}
                            </option>
                          ))}
                        </select>
                      </div>
                    </div>

                    {/* Sort Options */}
                    <div className="lg:w-48">
                      <div className="relative">
                        <Icon
                          name="ArrowUpDown"
                          size={18}
                          className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 z-10"
                        />
                        <select
                          value={sortBy}
                          onChange={(e) => setSortBy(e.target.value)}
                          className="w-full pl-10 pr-4 py-3 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent appearance-none shadow-sm"
                        >
                          <option value="date">Sort by Date (Newest)</option>
                          <option value="name">Sort by Name (A-Z)</option>
                          <option value="size">Sort by Size</option>
                          <option value="downloads">Sort by Downloads</option>
                        </select>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </section>

          {/* Documents Grid */}
          <section className="py-16 lg:py-20">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              {/* Results Summary */}
              <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-8 gap-4">
                <div className="flex items-center space-x-4">
                  <h2 className="font-heading font-semibold text-2xl lg:text-3xl text-gray-900">
                    Documents ({sortedDocuments.length})
                  </h2>
                  {selectedCategory !== "all" && (
                    <span className={`px-4 py-1 ${getCategoryColor(selectedCategory).replace('text-', 'bg-')}/10 ${getCategoryColor(selectedCategory)} rounded-full text-sm font-medium border ${getCategoryColor(selectedCategory).replace('text-', 'border-')}/20`}>
                      {categories.find((cat) => cat.id === selectedCategory)?.name}
                    </span>
                  )}
                </div>
                <div className="flex items-center space-x-2 text-sm text-gray-600">
                  <Icon name="Info" size={14} />
                  <span>
                    Showing {sortedDocuments.length} of {documents.length} documents
                  </span>
                </div>
              </div>

              {/* Loading State */}
              {loading && (
                <div className="flex flex-col items-center justify-center py-20">
                  <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                  <p className="text-gray-600">Loading documents...</p>
                </div>
              )}

              {/* Error State */}
              {error && !loading && (
                <div className="bg-red-50 border border-red-200 rounded-2xl p-8 text-center my-8">
                  <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icon name="AlertCircle" size={32} className="text-red-600" />
                  </div>
                  <h3 className="font-heading font-semibold text-xl text-red-800 mb-2">
                    Unable to Load Documents
                  </h3>
                  <p className="text-red-600 mb-4">{error}</p>
                  <button
                    onClick={() => window.location.reload()}
                    className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                  >
                    Retry
                  </button>
                </div>
              )}

              {/* Documents Grid */}
              {!loading && !error && (
                <>
                  {sortedDocuments.length > 0 ? (
                    <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                      {sortedDocuments.map((doc) => (
                        <div
                          key={doc._id || Math.random().toString(36).substr(2, 9)}
                          className="group bg-white border border-gray-200 rounded-2xl p-6 shadow-sm hover:shadow-xl transition-all duration-300 hover:border-blue-200 hover:-translate-y-1"
                        >
                          {/* Document Header */}
                          <div className="flex items-start justify-between mb-4">
                            <div className="flex items-center space-x-3">
                              <div className="w-12 h-12 bg-blue-50 rounded-xl flex items-center justify-center group-hover:bg-blue-100 transition-colors">
                                <Icon
                                  name={getFileTypeIcon(doc.fileType)}
                                  size={24}
                                  className="text-blue-600"
                                />
                              </div>
                              <div>
                                <h3 className="font-heading font-semibold text-lg text-gray-900 line-clamp-1">
                                  {doc.name}
                                </h3>
                                <p className={`text-sm font-medium ${getCategoryColor(doc.category)}`}>
                                  {categories.find((cat) => cat.id === doc.category)?.name || "Other"}
                                </p>
                              </div>
                            </div>
                            <div className="flex flex-col items-end gap-1">
                              <span className="text-xs font-medium px-2 py-1 bg-gray-100 text-gray-600 rounded">
                                {doc.fileType}
                              </span>
                              <span className="text-xs text-gray-500 flex items-center gap-1">
                                <Icon name="Download" size={10} />
                                {doc.downloads || 0}
                              </span>
                            </div>
                          </div>

                          {/* Document Description */}
                          <p className="text-sm text-gray-600 mb-4 line-clamp-2 min-h-[40px]">
                            {doc.description}
                          </p>

                          {/* Document Meta */}
                          <div className="flex items-center justify-between text-xs text-gray-500 mb-6">
                            <div className="flex items-center space-x-4">
                              <span className="flex items-center space-x-1">
                                <Icon name="HardDrive" size={12} />
                                <span>{formatFileSize(doc.fileSize)}</span>
                              </span>
                              <span className="flex items-center space-x-1">
                                <Icon name="Calendar" size={12} />
                                <span>{formatDate(doc.uploadDate)}</span>
                              </span>
                            </div>
                            {doc.createdAt && doc.createdAt !== doc.uploadDate && (
                              <span className="text-gray-400">
                                Added {formatDate(doc.createdAt)}
                              </span>
                            )}
                          </div>

                          {/* Action Buttons */}
                          <div className="flex gap-2">
                            <button
                              onClick={() => handleView(doc)}
                              disabled={downloading[doc._id]}
                              className="flex-1 bg-gradient-to-r from-blue-500 to-blue-600 text-white py-3 px-4 rounded-xl font-medium hover:from-blue-600 hover:to-blue-700 transition-all duration-300 flex items-center justify-center space-x-2 group/btn shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                              <Icon name="Eye" size={16} className="group-hover/btn:scale-110 transition-transform" />
                              <span>Preview</span>
                            </button>
                            <button
                              onClick={() => handleDownload(doc)}
                              disabled={downloading[doc._id]}
                              className="flex-1 bg-gradient-to-r from-gray-100 to-gray-50 text-gray-700 py-3 px-4 rounded-xl font-medium hover:from-gray-200 hover:to-gray-100 transition-all duration-300 flex items-center justify-center space-x-2 group/btn border border-gray-200 hover:border-gray-300 disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                              {downloading[doc._id] ? (
                                <>
                                  <div className="w-4 h-4 border-2 border-gray-400 border-t-transparent rounded-full animate-spin"></div>
                                  <span>Downloading...</span>
                                </>
                              ) : (
                                <>
                                  <Icon name="Download" size={16} className="group-hover/btn:translate-y-0.5 transition-transform" />
                                  <span>Download</span>
                                </>
                              )}
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    // Empty State
                    <div className="text-center py-16 bg-gradient-to-b from-gray-50 to-white rounded-2xl border border-gray-200">
                      <div className="w-24 h-24 bg-gradient-to-br from-gray-100 to-gray-200 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Icon
                          name="FileSearch"
                          size={48}
                          className="text-gray-400"
                        />
                      </div>
                      <h3 className="font-heading font-semibold text-xl text-gray-900 mb-2">
                        No documents found
                      </h3>
                      <p className="text-gray-600 mb-6 max-w-md mx-auto">
                        {searchTerm || selectedCategory !== "all" 
                          ? "Try adjusting your search terms or category filter" 
                          : "No documents available in the library yet"}
                      </p>
                      {(searchTerm || selectedCategory !== "all") && (
                        <button
                          onClick={() => {
                            setSearchTerm("");
                            setSelectedCategory("all");
                          }}
                          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                        >
                          Clear Filters
                        </button>
                      )}
                    </div>
                  )}
                </>
              )}
            </div>
          </section>

          {/* Categories Quick Access */}
          <section className="py-16 lg:py-20 bg-gradient-to-b from-gray-50 to-white">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h2 className="font-heading font-bold text-3xl lg:text-4xl text-gray-900 mb-4">
                  Browse by Category
                </h2>
                <p className="font-body text-lg text-gray-600 max-w-2xl mx-auto">
                  Quickly access documents by category
                </p>
              </div>

              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {categories.slice(1).map((category) => {
                  const count = getCategoryCount(category.id);
                  return (
                    <div
                      key={category.id}
                      onClick={() => setSelectedCategory(category.id)}
                      className={`group bg-white border border-gray-200 rounded-2xl p-6 text-center hover:shadow-xl transition-all duration-300 cursor-pointer hover:border-${category.color.split('-')[1]}-200 relative overflow-hidden`}
                    >
                      <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-gray-200 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                      <div className={`w-16 h-16 ${category.color.replace('text-', 'bg-')}/10 rounded-2xl flex items-center justify-center mx-auto mb-4 group-hover:${category.color.replace('text-', 'bg-')}/20 transition-colors`}>
                        <Icon
                          name={category.icon}
                          size={32}
                          className={category.color}
                        />
                      </div>
                      <h3 className="font-heading font-semibold text-lg text-gray-900 mb-2">
                        {category.name}
                      </h3>
                      <p className="text-sm text-gray-600">
                        {count} document{count !== 1 ? 's' : ''}
                      </p>
                      <div className="mt-4 pt-4 border-t border-gray-100">
                        <span className={`text-sm font-medium ${category.color} flex items-center justify-center space-x-1`}>
                          <Icon name="ChevronRight" size={14} />
                          <span>Browse Category</span>
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>
        </main>

        {/* Document Viewer Modal */}
        <DocumentViewer
          url={viewerOpen ? viewerUrl : ""}
          name={viewerName}
          onClose={() => setViewerOpen(false)}
        />

        {/* Footer */}
        <Footer />
      </div>
    </>
  );
};

export default Documents;