import React from 'react';
import Icon from '../AppIcon';

export const Alert = ({
  children,
  className = '',
  variant = 'default',
  icon,
  ...props
}) => {
  const variants = {
    default: 'bg-card border-border text-foreground',
    destructive: 'bg-destructive/10 border-destructive/20 text-destructive',
    success: 'bg-emerald-500/10 border-emerald-500/20 text-emerald-600',
    warning: 'bg-amber-500/10 border-amber-500/20 text-amber-600',
    info: 'bg-blue-500/10 border-blue-500/20 text-blue-600',
  };

  const iconMap = {
    default: 'Info',
    destructive: 'AlertCircle',
    success: 'CheckCircle',
    warning: 'AlertTriangle',
    info: 'Info',
  };

  const currentIcon = icon || iconMap[variant];

  return (
    <div
      className={`flex items-start p-4 rounded-lg border ${variants[variant]} ${className}`}
      role="alert"
      {...props}
    >
      {currentIcon && (
        <Icon 
          name={currentIcon} 
          size={20} 
          className="mr-3 flex-shrink-0 mt-0.5"
        />
      )}
      <div className="flex-1">{children}</div>
    </div>
  );
};

// Export both components
export default  Alert 