import React from 'react';
import Icon from '../../../components/AppIcon';

const ArticleHeader = ({ post}) => {
  return (
    <header className="relative mb-o">
      {/* Featured Image */}
      <div className="aspect-video bg-muted overflow-hidden">
        
        <embed src="../../../assets/library/html.pdf" className="w-full h-full object-cover"type="" />
      </div>

      {/* Article Meta */}
      <div className="p-6 lg:p-8">

        {/* Title */}
        <h1 className="font-heading font-bold text-1xl lg:text-2xl text-foreground mb-6 leading-tight">
          {post?.title}
        </h1>

        {/* Author Info */}
        <div className="flex items-center justify-between pb-6 border-b border-border">

        </div>

        {/* Article Stats */}
        <div className="flex items-center justify-between pt-4 ">          
          <div className="text-muted-foreground text-sm ">
            Powered by <span className="font-semibold text-blue-700">
          <a href="https://gnintellex.netlify.app/"> GNA IntelleX</a></span>
          </div>
        </div>
      </div>
    </header>
  );
};

export default ArticleHeader;



