import React, { useState, useEffect, useCallback } from "react";
import PublicHeader from "components/ui/PublicHeader";
import Footer from "components/ui/Footer";
import Icon from "../components/AppIcon";
import Image from "../components/AppImage";

const PhotoGallery = () => {
  const [selectedImage, setSelectedImage] = useState(null);
  const [activeCategory, setActiveCategory] = useState("All");
  const [loadedImages, setLoadedImages] = useState({});
  const [galleryImages, setGalleryImages] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch gallery data from API
  useEffect(() => {
    const fetchGalleryData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const response = await fetch("https://new-school-web-90vd.onrender.com/gallery/all");
        
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const result = await response.json();
        console.log("API Response:", result); // Debug log
        
        // Handle different response formats
        let data = [];
        if (Array.isArray(result)) {
          data = result;
        } else if (result.data && Array.isArray(result.data)) {
          data = result.data;
        } else if (result.gallery && Array.isArray(result.gallery)) {
          data = result.gallery;
        } else if (result.images && Array.isArray(result.images)) {
          data = result.images;
        } else {
          console.warn("Unexpected API response format:", result);
          data = [];
        }
        
        // Transform API data to match your component structure
        const transformedData = data.map((item, index) => ({
          id: item._id || item.id || `img-${index}`,
          src: item.imageUrl || item.src || item.url || item.image,
          alt: item.altText || item.alt || item.title || `Gallery Image ${index + 1}`,
          category: item.category || "General",
          title: item.title || `Image ${index + 1}`,
          description: item.description || "No description available",
          date: item.createdAt || item.date || new Date().toISOString(),
          featured: item.featured || index < 3 // Mark first 3 items as featured
        }));
        
        console.log("Transformed Data:", transformedData); // Debug log
        setGalleryImages(transformedData);
      } catch (err) {
        console.error("Error fetching gallery data:", err);
        setError(`Failed to load gallery images: ${err.message}`);
        setGalleryImages([]); // Set empty array on error
      } finally {
        setIsLoading(false);
      }
    };

    fetchGalleryData();
  }, []);

  // Dynamically generate categories from fetched data
  const categories = [
    "All",
    ...new Set(galleryImages.map((img) => img.category)),
  ];

  const filteredImages =
    activeCategory === "All"
      ? galleryImages
      : galleryImages.filter((img) => img.category === activeCategory);

  const featuredImages = galleryImages.filter((img) => img.featured);

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (!selectedImage) return;
      
      if (e.key === "Escape") closeModal();
      if (e.key === "ArrowRight") nextImage();
      if (e.key === "ArrowLeft") prevImage();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [selectedImage]);

  const openModal = useCallback((image) => {
    setSelectedImage(image);
    document.body.style.overflow = "hidden";
  }, []);

  const closeModal = useCallback(() => {
    setSelectedImage(null);
    document.body.style.overflow = "unset";
  }, []);

  const nextImage = useCallback(() => {
    if (!selectedImage || filteredImages.length === 0) return;
    const currentIndex = filteredImages.findIndex(
      (img) => img.id === selectedImage.id
    );
    const nextIndex = (currentIndex + 1) % filteredImages.length;
    setSelectedImage(filteredImages[nextIndex]);
  }, [selectedImage, filteredImages]);

  const prevImage = useCallback(() => {
    if (!selectedImage || filteredImages.length === 0) return;
    const currentIndex = filteredImages.findIndex(
      (img) => img.id === selectedImage.id
    );
    const prevIndex =
      (currentIndex - 1 + filteredImages.length) % filteredImages.length;
    setSelectedImage(filteredImages[prevIndex]);
  }, [selectedImage, filteredImages]);

  const handleImageLoad = (id) => {
    setLoadedImages((prev) => ({ ...prev, [id]: true }));
  };

  const formatDate = (dateString) => {
    try {
      return new Date(dateString).toLocaleDateString("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric",
      });
    } catch (error) {
      return "Date not available";
    }
  };

  // Loading state
  if (isLoading) {
    return (
      <>
        <PublicHeader />
        <section className="relative overflow-hidden bg-gradient-to-br from-primary/10 via-background to-secondary/5 py-20 lg:py-28">
          <div className="absolute inset-0 bg-grid-pattern opacity-5"></div>
          <div className="max-w-7xl mx-auto px-4 lg:px-6 relative">
            <div className="text-center max-w-3xl mx-auto">
              <div className="flex flex-col items-center justify-center min-h-[60vh]">
                <div className="w-16 h-16 border-4 border-primary/30 border-t-primary rounded-full animate-spin mb-6"></div>
                <h2 className="font-heading font-semibold text-xl text-foreground mb-3">
                  Loading Gallery
                </h2>
                <p className="font-body text-muted-foreground">
                  Loading your memorable moments...
                </p>
              </div>
            </div>
          </div>
        </section>
        <Footer />
      </>
    );
  }

  // Error state
  if (error) {
    return (
      <>
        <PublicHeader />
        <section className="relative overflow-hidden bg-gradient-to-br from-primary/10 via-background to-secondary/5 py-20 lg:py-28">
          <div className="absolute inset-0 bg-grid-pattern opacity-5"></div>
          <div className="max-w-7xl mx-auto px-4 lg:px-6 relative">
            <div className="text-center max-w-3xl mx-auto">
              <div className="flex flex-col items-center justify-center min-h-[60vh]">
                <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-6">
                  <Icon name="AlertCircle" size={32} className="text-red-500" />
                </div>
                <h2 className="font-heading font-semibold text-xl text-foreground mb-3">
                  Something went wrong
                </h2>
                <p className="font-body text-muted-foreground mb-6">
                  {error}
                </p>
                <div className="flex gap-4">
                  <button
                    onClick={() => window.location.reload()}
                    className="px-6 py-3 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-colors"
                  >
                    Try Again
                  </button>
                  <button
                    onClick={() => {
                      // Fallback to sample data if API fails
                      const sampleData = [
                        {
                          id: 1,
                          src: "https://images.unsplash.com/photo-1523050854058-8df90110c9f1?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1000&q=80",
                          alt: "Sample School Event",
                          category: "Events",
                          title: "Sample Event",
                          description: "This is sample data because the API is not available",
                          date: new Date().toISOString(),
                          featured: true,
                        },
                      ];
                      setGalleryImages(sampleData);
                      setError(null);
                    }}
                    className="px-6 py-3 border border-border text-foreground rounded-lg font-medium hover:bg-muted transition-colors"
                  >
                    Use Sample Data
                  </button>
                </div>
              </div>
            </div>
          </div>
        </section>
        <Footer />
      </>
    );
  }

  return (
    <>
      <PublicHeader />
      
      {/* Hero Section */}
      <section className="relative overflow-hidden bg-gradient-to-br from-primary/10 via-background to-secondary/5 py-20 lg:py-28">
        <div className="absolute inset-0 bg-grid-pattern opacity-5"></div>
        <div className="max-w-7xl mx-auto px-4 lg:px-6 relative">
          <div className="text-center max-w-3xl mx-auto">
            <span className="inline-block px-4 py-2 rounded-full bg-primary/10 text-primary font-medium text-sm mb-6">
              Visual Journey
            </span>
            <h1 className="font-heading font-bold text-4xl lg:text-5xl xl:text-6xl text-foreground mb-6 leading-tight">
              School <span className="text-primary">Gallery</span>
            </h1>
            <p className="font-body text-xl text-muted-foreground max-w-2xl mx-auto leading-relaxed">
              Capturing moments of excellence, innovation, and community spirit
            </p>
            <div className="flex items-center justify-center gap-4 mt-8">
              <div className="flex items-center">
                <div className="w-2 h-2 bg-primary rounded-full mr-2"></div>
                <span className="font-body text-sm text-muted-foreground">
                  {galleryImages.length} Photos
                </span>
              </div>
              <div className="w-1 h-1 bg-muted-foreground/20 rounded-full"></div>
              <div className="flex items-center">
                <div className="w-2 h-2 bg-secondary rounded-full mr-2"></div>
                <span className="font-body text-sm text-muted-foreground">
                  {categories.length - 1} Categories
                </span>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="py-16 lg:py-24 bg-background">
        <div className="max-w-7xl mx-auto px-4 lg:px-6">
          {/* Featured Images Carousel - Only show if we have featured images */}
          {featuredImages.length > 0 && (
            <div className="mb-16">
              <div className="flex items-center justify-between mb-8">
                <div>
                  <h3 className="font-heading font-bold text-2xl text-foreground mb-2">
                    Featured Moments
                  </h3>
                  <p className="font-body text-muted-foreground">
                    Highlighted events and achievements
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-primary rounded-full"></div>
                  <div className="w-2 h-2 bg-primary/30 rounded-full"></div>
                  <div className="w-2 h-2 bg-primary/30 rounded-full"></div>
                </div>
              </div>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {featuredImages.slice(0, 2).map((image) => (
                  <div
                    key={image.id}
                    className="group relative overflow-hidden rounded-2xl shadow-2xl hover:shadow-3xl transition-all duration-500 cursor-pointer"
                    onClick={() => openModal(image)}
                  >
                    <div className="relative h-80 lg:h-96">
                      <Image
                        src={image.src}
                        alt={image.alt}
                        className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700"
                        onLoad={() => handleImageLoad(image.id)}
                      />
                      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/40 to-transparent">
                        <div className="absolute bottom-0 left-0 right-0 p-6 lg:p-8">
                          <div className="flex items-center justify-between mb-4">
                            <span className="inline-block px-3 py-1 bg-primary text-primary-foreground rounded-full text-sm font-medium">
                              Featured
                            </span>
                            <Icon 
                              name="ExternalLink" 
                              size={20} 
                              className="text-white/80 group-hover:text-white transition-colors" 
                            />
                          </div>
                          <h4 className="font-heading font-bold text-2xl lg:text-3xl text-white mb-3">
                            {image.title}
                          </h4>
                          <p className="font-body text-white/90 mb-3 line-clamp-2">
                            {image.description || "No description available"}
                          </p>
                          <div className="flex items-center gap-4">
                            <span className="font-body text-sm text-white/70">
                              {formatDate(image.date)}
                            </span>
                            <div className="flex items-center gap-2">
                              <div className="w-1 h-1 bg-white/50 rounded-full"></div>
                              <div className="w-1 h-1 bg-white/50 rounded-full"></div>
                              <div className="w-1 h-1 bg-white/50 rounded-full"></div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Category Filter */}
          <div className="mb-12">
            <div className="text-center mb-8">
              <h3 className="font-heading font-bold text-2xl text-foreground mb-3">
                Browse by Category
              </h3>
              <p className="font-body text-muted-foreground max-w-2xl mx-auto">
                Explore our collection of memorable moments
              </p>
            </div>
            <div className="flex flex-wrap justify-center gap-2 mb-8">
              {categories.map((category) => (
                <button
                  key={category}
                  onClick={() => setActiveCategory(category)}
                  className={`px-5 py-2.5 rounded-xl font-body font-medium transition-all duration-300 transform hover:-translate-y-0.5 ${
                    activeCategory === category
                      ? "bg-primary text-primary-foreground shadow-lg shadow-primary/25"
                      : "bg-white text-foreground shadow-md hover:shadow-lg hover:bg-primary/5"
                  }`}
                >
                  {category}
                </button>
              ))}
            </div>
            <div className="text-center">
              <span className="inline-block px-4 py-2 rounded-lg bg-muted text-muted-foreground text-sm font-medium">
                {filteredImages.length} {filteredImages.length === 1 ? 'photo' : 'photos'} in {activeCategory}
              </span>
            </div>
          </div>

          {/* Gallery Grid */}
          {galleryImages.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((image) => (
                <div
                  key={image.id}
                  className="group relative overflow-hidden rounded-2xl bg-white shadow-lg hover:shadow-2xl transition-all duration-500 cursor-pointer border border-gray-100 hover:border-primary/20"
                  onClick={() => openModal(image)}
                >
                  <div className="relative overflow-hidden aspect-square">
                    {!loadedImages[image.id] && (
                      <div className="absolute inset-0 bg-gradient-to-br from-gray-100 to-gray-200 animate-pulse"></div>
                    )}
                    <Image
                      src={image.src}
                      alt={image.alt}
                      className={`w-full h-full object-cover transition-all duration-700 ${
                        loadedImages[image.id] 
                          ? 'group-hover:scale-110 opacity-100' 
                          : 'opacity-0'
                      }`}
                      onLoad={() => handleImageLoad(image.id)}
                      onError={(e) => {
                        console.error(`Failed to load image: ${image.src}`);
                        e.target.style.display = 'none';
                      }}
                    />
                    
                    {/* Hover Overlay */}
                    <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                      <div className="absolute bottom-0 left-0 right-0 p-5 transform translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
                        <div className="flex items-center justify-between mb-3">
                          <span className="inline-block px-3 py-1 bg-primary/90 text-primary-foreground rounded-lg text-xs font-semibold">
                            {image.category}
                          </span>
                          <div className="w-10 h-10 rounded-full bg-white/20 backdrop-blur-sm flex items-center justify-center">
                            <Icon name="ZoomIn" size={18} className="text-white" />
                          </div>
                        </div>
                        <h4 className="font-heading font-semibold text-lg text-white mb-2 line-clamp-1">
                          {image.title}
                        </h4>
                        <p className="font-body text-sm text-white/90 mb-3 line-clamp-2">
                          {image.description || "No description available"}
                        </p>
                        <div className="flex items-center gap-2">
                          <Icon name="Calendar" size={14} className="text-white/70" />
                          <span className="font-body text-xs text-white/70">
                            {formatDate(image.date)}
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                  
                  {/* Bottom Info (visible on mobile) */}
                  <div className="p-4 lg:hidden">
                    <div className="flex items-center justify-between mb-2">
                      <h4 className="font-heading font-semibold text-foreground line-clamp-1">
                        {image.title}
                      </h4>
                      <span className="text-xs px-2 py-1 bg-primary/10 text-primary rounded">
                        {image.category}
                      </span>
                    </div>
                    <p className="font-body text-sm text-muted-foreground line-clamp-2">
                      {image.description || "No description available"}
                    </p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            // Empty state when no images are available
            <div className="text-center py-16">
              <div className="w-24 h-24 mx-auto mb-6 rounded-full bg-gray-50 flex items-center justify-center">
                <Icon name="Image" size={40} className="text-gray-300" />
              </div>
              <h4 className="font-heading font-semibold text-xl text-foreground mb-3">
                No photos available yet
              </h4>
              <p className="font-body text-muted-foreground max-w-md mx-auto">
                Check back soon for gallery updates!
              </p>
            </div>
          )}

          {/* Filtered empty state */}
          {galleryImages.length > 0 && filteredImages.length === 0 && (
            <div className="text-center py-16">
              <div className="w-24 h-24 mx-auto mb-6 rounded-full bg-gray-50 flex items-center justify-center">
                <Icon name="Image" size={40} className="text-gray-300" />
              </div>
              <h4 className="font-heading font-semibold text-xl text-foreground mb-3">
                No photos found
              </h4>
              <p className="font-body text-muted-foreground max-w-md mx-auto">
                We couldn't find any photos in the {activeCategory} category. Try selecting a different category.
              </p>
            </div>
          )}
        </div>
      </section>

      {/* Enhanced Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[100] bg-black/95 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-300">
          <div className="relative max-w-6xl w-full max-h-[90vh] bg-card rounded-2xl overflow-hidden shadow-2xl">
            {/* Close Button */}
            <button
              onClick={closeModal}
              className="absolute top-6 right-6 z-20 w-12 h-12 bg-black/60 hover:bg-black/80 text-white rounded-xl flex items-center justify-center transition-all duration-300 hover:scale-105 backdrop-blur-sm"
              aria-label="Close modal"
            >
              <Icon name="X" size={24} />
            </button>

            {/* Navigation Buttons */}
            <button
              onClick={prevImage}
              className="absolute left-6 top-1/2 transform -translate-y-1/2 z-20 w-12 h-12 bg-black/60 hover:bg-black/80 text-white rounded-xl flex items-center justify-center transition-all duration-300 hover:scale-105 backdrop-blur-sm group"
              aria-label="Previous image"
            >
              <Icon name="ChevronLeft" size={24} className="group-hover:-translate-x-1 transition-transform" />
            </button>

            <button
              onClick={nextImage}
              className="absolute right-6 top-1/2 transform -translate-y-1/2 z-20 w-12 h-12 bg-black/60 hover:bg-black/80 text-white rounded-xl flex items-center justify-center transition-all duration-300 hover:scale-105 backdrop-blur-sm group"
              aria-label="Next image"
            >
              <Icon name="ChevronRight" size={24} className="group-hover:translate-x-1 transition-transform" />
            </button>

            {/* Image Counter */}
            <div className="absolute top-6 left-6 z-20 px-4 py-2 bg-black/60 text-white rounded-xl text-sm font-medium backdrop-blur-sm">
              {filteredImages.findIndex(img => img.id === selectedImage.id) + 1} / {filteredImages.length}
            </div>

            {/* Image Container */}
            <div className="relative h-[60vh] flex items-center justify-center p-8">
              <div className="relative w-full h-full flex items-center justify-center">
                <Image
                  src={selectedImage.src}
                  alt={selectedImage.alt}
                  className="max-w-full max-h-full object-contain rounded-lg"
                  onError={(e) => {
                    console.error(`Failed to load modal image: ${selectedImage.src}`);
                    e.target.src = "https://images.unsplash.com/photo-1523050854058-8df90110c9f1?ixlib=rb-4.0.3&auto=format&fit=crop&w=1000&q=80";
                  }}
                />
              </div>
            </div>

            {/* Image Info */}
            <div className="p-8 border-t border-border">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                  <div className="flex items-center gap-4 mb-4">
                    <h3 className="font-heading font-bold text-2xl text-foreground">
                      {selectedImage.title}
                    </h3>
                    <span className="px-3 py-1 bg-primary/10 text-primary rounded-full text-sm font-semibold">
                      {selectedImage.category}
                    </span>
                  </div>
                  <p className="font-body text-lg text-muted-foreground mb-6 leading-relaxed">
                    {selectedImage.description || "No description available"}
                  </p>
                </div>
                <div className="lg:pl-8 lg:border-l border-border">
                  <div className="space-y-4">
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <Icon name="Calendar" size={18} className="text-muted-foreground" />
                        <h4 className="font-heading font-semibold text-foreground">Date</h4>
                      </div>
                      <p className="font-body text-muted-foreground">
                        {formatDate(selectedImage.date)}
                      </p>
                    </div>
                    <div>
                      <div className="flex items-center gap-2 mb-2">
                        <Icon name="Image" size={18} className="text-muted-foreground" />
                        <h4 className="font-heading font-semibold text-foreground">Details</h4>
                      </div>
                      <p className="font-body text-sm text-muted-foreground">
                        High-resolution image • Download available
                      </p>
                    </div>
                  </div>
                </div>
              </div>
              
              {/* Action Buttons */}
              <div className="flex items-center justify-between mt-8 pt-8 border-t border-border">
                <div className="flex items-center gap-4">
                  <button 
                    onClick={() => window.open(selectedImage.src, '_blank')}
                    className="flex items-center gap-2 px-4 py-2.5 rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 transition-colors font-medium"
                  >
                    <Icon name="Download" size={18} />
                    Download
                  </button>
                  <button className="flex items-center gap-2 px-4 py-2.5 rounded-lg border border-border hover:bg-muted transition-colors font-medium">
                    <Icon name="Share2" size={18} />
                    Share
                  </button>
                </div>
                <div className="flex items-center gap-4">
                  <button 
                    onClick={prevImage}
                    className="flex items-center gap-2 px-4 py-2.5 rounded-lg border border-border hover:bg-muted transition-colors font-medium"
                  >
                    <Icon name="ChevronLeft" size={18} />
                    Previous
                  </button>
                  <button 
                    onClick={nextImage}
                    className="flex items-center gap-2 px-4 py-2.5 rounded-lg border border-border hover:bg-muted transition-colors font-medium"
                  >
                    Next
                    <Icon name="ChevronRight" size={18} />
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
      <Footer />
    </>
  );
};

export default PhotoGallery;