import React from 'react';
import { Link } from 'react-router-dom';
import { format } from 'date-fns';
import Icon from '../../../components/AppIcon';
import AppImage from '../../../components/AppImage';

const CategoryFilter = ({ categories, selectedCategory, onCategoryChange }) => {
  return (
    <div className="bg-card rounded-lg border border-border shadow-card p-6 mb-6">
      <h3 className="font-heading font-bold text-lg text-foreground mb-4 flex items-center">
        <Icon name="Filter" size={20} className="mr-2 text-primary" />
        Categories
      </h3>
      <div className="space-y-2">
        {categories?.map((category) => (
          <button
            key={category}
            onClick={() => onCategoryChange?.(category)}
            className={`flex items-center justify-between w-full px-3 py-2 rounded-md font-body font-medium transition-smooth ${
              selectedCategory === category
                ? 'bg-primary text-primary-foreground'
                : 'text-foreground hover:bg-muted'
            }`}
          >
            <span>{category}</span>
            {selectedCategory === category && (
              <Icon name="Check" size={16} />
            )}
          </button>
        ))}
      </div>
    </div>
  );
};

const PopularTags = ({ tags, onTagClick }) => {
  if (!tags || tags?.length === 0) return null;

  return (
    <div className="bg-card rounded-lg border border-border shadow-card p-6 mb-6">
      <h3 className="font-heading font-bold text-lg text-foreground mb-4 flex items-center">
        <Icon name="Hash" size={20} className="mr-2 text-primary" />
        Popular Tags
      </h3>
      <div className="flex flex-wrap gap-2">
        {tags?.map(({ tag, count }) => (
          <button
            key={tag}
            onClick={() => onTagClick?.(tag)}
            className="inline-flex items-center px-3 py-1.5 rounded-full text-sm font-medium bg-muted text-muted-foreground hover:bg-primary hover:text-primary-foreground transition-smooth group"
          >
            #{tag}
            <span className="ml-1.5 text-xs opacity-75 group-hover:opacity-100">
              {count}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
};

const RecentPosts = ({ posts }) => {
  if (!posts || posts?.length === 0) return null;

  return (
    <div className="bg-card rounded-lg border border-border shadow-card p-6 mb-6">
      <h3 className="font-heading font-bold text-lg text-foreground mb-4 flex items-center">
        <Icon name="Clock" size={20} className="mr-2 text-primary" />
        Recent Posts
      </h3>
      <div className="space-y-4">
        {posts?.map((post) => (
          <article key={post?.id} className="group">
            <Link 
              to={`/blog-post-view?slug=${post?.slug}`}
              className="flex space-x-3 hover:bg-muted/50 p-2 rounded-lg transition-smooth -m-2"
            >
              <div className="w-16 h-16 bg-muted rounded-lg overflow-hidden flex-shrink-0">
                <AppImage
                  src={post?.featuredImage}
                  alt={post?.title}
                  className="w-full h-full object-cover group-hover:scale-105 transition-smooth duration-300"
                />
              </div>
              <div className="min-w-0 flex-1">
                <h4 className="font-body font-medium text-foreground text-sm line-clamp-2 group-hover:text-primary transition-smooth mb-1">
                  {post?.title}
                </h4>
                <div className="flex items-center text-xs text-muted-foreground">
                  <span>{format(new Date(post?.publishedDate), 'MMM dd')}</span>
                  <span className="mx-1">•</span>
                  <span>{post?.readingTime}</span>
                </div>
              </div>
            </Link>
          </article>
        ))}
      </div>
    </div>
  );
};

const Newsletter = () => {
  const handleSubscribe = (e) => {
    e?.preventDefault();
    // Handle newsletter subscription
    alert('Thank you for subscribing! We\'ll send you updates about new articles.');
  };

  return (
    <div className="bg-gradient-to-br from-primary/10 to-accent/10 rounded-lg border border-border shadow-card p-6">
      <h3 className="font-heading font-bold text-lg text-foreground mb-2 flex items-center">
        <Icon name="Mail" size={20} className="mr-2 text-primary" />
        Newsletter
      </h3>
      <p className="font-body text-muted-foreground text-sm mb-4">
        Stay updated with our latest articles and community insights.
      </p>
      <form onSubmit={handleSubscribe} className="space-y-3">
        <input
          type="email"
          placeholder="Your email address"
          required
          className="w-full px-3 py-2 border border-input bg-card rounded-lg font-body text-sm placeholder:text-muted-foreground focus:ring-2 focus:ring-ring focus:border-transparent transition-smooth"
        />
        <button
          type="submit"
          className="w-full bg-primary text-primary-foreground px-4 py-2 rounded-lg font-body font-medium text-sm hover:bg-primary/90 transition-smooth flex items-center justify-center"
        >
          <Icon name="Send" size={16} className="mr-2" />
          Subscribe
        </button>
      </form>
      <p className="font-body text-xs text-muted-foreground mt-2">
        We respect your privacy. No spam, ever.
      </p>
    </div>
  );
};

const Sidebar = ({ 
  categories, 
  selectedCategory, 
  onCategoryChange, 
  popularTags, 
  recentPosts,
  onTagClick 
}) => {
  return (
    <div className="space-y-6">
      <CategoryFilter 
        categories={categories}
        selectedCategory={selectedCategory}
        onCategoryChange={onCategoryChange}
      />
      
      <RecentPosts posts={recentPosts} />
      
      <PopularTags 
        tags={popularTags}
        onTagClick={onTagClick}
      />
      
      <Newsletter />
    </div>
  );
};

export default Sidebar;