import React from "react";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";
import EventsSection from "./components/EventsSection";
import Footer from "../../components/ui/Footer";

const PublicEvent = () => {
  return (
    <>
      <Helmet>
        <title>Event | GS DES PARENTS </title>
        <meta
          name="description"
          content="Join GS DES PARENTS's community platform dedicated to fostering inclusive dialogue, promoting social justice, and creating positive change across Rwanda through collective action."
        />
        <meta
          name="keywords"
          content="GS DES PARENTS, CEFOTEC, GSPHUYE, Rwanda, community, social justice, advocacy, empowerment, dialogue, UNMUTE"
        />
        <meta property="og:title" content="Event - GS DES PARENTS" />
        <meta
          property="og:description"
          content="Join our community platform for inclusive dialogue and positive change in Rwanda"
        />
        <meta property="og:type" content="website" />
        <meta name="twitter:card" content="summary_large_image" />
        <link rel="canonical" href="/" />
      </Helmet>

      <div className="min-h-screen bg-background">
        {/* Header */}
        <PublicHeader />

        {/* Main Content */}
        <main className="pt-16">
          {/* Events Section */}
          <EventsSection />
        </main>

        {/* Footer */}
        <Footer />
      </div>
    </>
  );
};

export default PublicEvent;
