import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import Image from "../../../components/AppImage";
import Button from "../../../components/ui/Button";

// Simple SVG icons
const StarIcon = () => (
  <svg className="w-4 h-4" viewBox="0 0 24 24" fill="currentColor">
    <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/>
  </svg>
);

const CheckIcon = () => (
  <svg className="w-5 h-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
    <path d="M20 6L9 17l-5-5" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const carouselImages = [
  "../../../assets/images/school1.jpg",
  "../../../assets/images/school2.jpeg",
  "../../../assets/images/school3.jpg",
];

const highlights = [
  "Rwanda's #1 School Since 1998",
  "Cambridge International Curriculum",
  "98% University Admission Rate",
  "Global Exchange Programs"
];

const HeroSection = () => {
  const [currentImage, setCurrentImage] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentImage((prev) => (prev + 1) % carouselImages.length);
    }, 4000);
    return () => clearInterval(interval);
  }, []);

  return (
    <>
      {/* Hero Section */}
      <section className="relative min-h-screen flex items-center overflow-hidden">
        {/* Background Images */}
        <div className="absolute inset-0">
          {carouselImages.map((src, index) => (
            <div
              key={index}
              className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${
                index === currentImage ? "opacity-100" : "opacity-0"
              }`}
            >
              <Image
                src={src}
                alt={`GS DES PARENTS Campus ${index + 1}`}
                className="w-full h-full object-cover"
              />
              <div className="absolute inset-0 bg-gradient-to-r from-black/60 via-black/40 to-transparent" />
            </div>
          ))}
        </div>

        {/* Content */}
        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 w-full">
          <div className="max-w-2xl">
            {/* Badge */}
            <div className="inline-flex items-center gap-2 bg-white/20 backdrop-blur-sm rounded-full px-4 py-2 mb-8 border border-white/30">
              <StarIcon className="text-yellow-400" />
              <span className="text-sm font-semibold text-white">
                Rwanda's Premier Institution
              </span>
            </div>

            {/* Main Heading */}
            <h1 className="text-5xl lg:text-7xl font-bold text-white mb-6 leading-tight">
              Excellence in <span className="text-primary">Education</span>
              <br />
              Since 1998
            </h1>

            {/* Description */}
            <p className="text-xl text-white/90 mb-8 leading-relaxed">
              GS DES PARENTS — Rwanda's first and foremost school, setting the standard 
              for academic excellence and leadership development.
            </p>

            {/* Highlights */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-10">
              {highlights.map((item) => (
                <div key={item} className="flex items-center gap-3">
                  <div className="w-6 h-6 bg-green-500 rounded-full flex items-center justify-center flex-shrink-0">
                    <CheckIcon className="text-white" />
                  </div>
                  <span className="text-white font-medium">{item}</span>
                </div>
              ))}
            </div>

            {/* CTA Buttons */}
            <div className="flex flex-col sm:flex-row gap-4">
              <Link to="/admissions">
                <Button
                  size="lg"
                  className="px-8 py-4 text-lg bg-primary hover:bg-primary-dark shadow-lg hover:shadow-xl transition-all"
                >
                  Start Your Journey
                </Button>
              </Link>
              <Link to="/about">
                <Button
                  variant="outline"
                  size="lg"
                  className="px-8 py-4 text-lg border-white text-white hover:bg-white/10"
                >
                  Discover More
                </Button>
              </Link>
            </div>
          </div>
        </div>

        {/* Image Indicators */}
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex gap-2">
          {carouselImages.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrentImage(index)}
              className={`w-3 h-3 rounded-full transition-all ${
                index === currentImage 
                  ? "bg-white scale-125" 
                  : "bg-white/50 hover:bg-white/80"
              }`}
              aria-label={`View image ${index + 1}`}
            />
          ))}
        </div>

        {/* Scroll Indicator */}
        <div className="absolute bottom-8 right-8 hidden lg:block">
          <div className="text-white text-sm font-medium rotate-90 origin-bottom-right">
            Scroll →
          </div>
        </div>
      </section>

      {/* Stats Section */}
      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12">
            <h2 className="text-4xl font-bold text-gray-900 mb-4">
              Leading <span className="text-primary">Rwandan Education</span>
            </h2>
            <p className="text-gray-600 max-w-2xl mx-auto">
              Setting benchmarks in academic excellence and student development
            </p>
          </div>

          <div className="grid md:grid-cols-3 gap-8">
            {/* Stat 1 */}
            <div className="text-center p-8 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors">
              <div className="text-5xl font-bold text-primary mb-2">25+</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">Years of Excellence</h3>
              <p className="text-gray-600">Pioneering quality education since 1998</p>
            </div>

            {/* Stat 2 */}
            <div className="text-center p-8 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors">
              <div className="text-5xl font-bold text-primary mb-2">#1</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">National Ranking</h3>
              <p className="text-gray-600">Consistently top-performing school</p>
            </div>

            {/* Stat 3 */}
            <div className="text-center p-8 rounded-2xl bg-gray-50 hover:bg-gray-100 transition-colors">
              <div className="text-5xl font-bold text-primary mb-2">98%</div>
              <h3 className="text-xl font-semibold text-gray-900 mb-2">Success Rate</h3>
              <p className="text-gray-600">University admission achievement</p>
            </div>
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-20 bg-gradient-to-r from-primary to-primary-dark">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <h2 className="text-4xl font-bold text-white mb-6">
            Ready to Join Rwanda's Best?
          </h2>
          <p className="text-xl text-white/90 mb-8">
            Limited spots available for the 2024 academic year. 
            Secure your child's future today.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link to="/apply">
              <Button
                size="lg"
                className="px-8 py-4 text-lg bg-white text-primary hover:bg-gray-100"
              >
                Apply Now
              </Button>
            </Link>
            <Link to="/contact">
              <Button
                variant="outline"
                size="lg"
                className="px-8 py-4 text-lg border-white text-white hover:bg-white/10"
              >
                Contact Admissions
              </Button>
            </Link>
          </div>
        </div>
      </section>
    </>
  );
};

export default HeroSection;