import React, { useState, useEffect } from "react";
import Icon from "../../components/AppIcon";
import Image from "../../components/AppImage";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";
import Footer from "../../components/ui/Footer";

const AdministrationMenu = () => {
  const [expandedMember, setExpandedMember] = useState(null);
  const [activeCategory, setActiveCategory] = useState("all");
  const [staffMembers, setStaffMembers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch data from API
  useEffect(() => {
    const fetchStaffMembers = async () => {
      try {
        setLoading(true);
        const response = await fetch("https://new-school-web-90vd.onrender.com/leader/select");
        
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const data = await response.json();
        
        // Handle different possible API response structures
        // API might return: { success: true, data: [] } or directly an array
        const members = Array.isArray(data) ? data : 
                       (data.data && Array.isArray(data.data)) ? data.data : 
                       (data.leaders && Array.isArray(data.leaders)) ? data.leaders : [];
        
        // Ensure each member has a unique key
        const membersWithKeys = members.map((member, index) => ({
          ...member,
          uniqueId: member.id || member._id || `member-${index}`
        }));
        
        setStaffMembers(membersWithKeys);
        setError(null);
      } catch (err) {
        console.error("Error fetching staff members:", err);
        setError("Failed to load staff members. Please try again later.");
      } finally {
        setLoading(false);
      }
    };

    fetchStaffMembers();
  }, []);

  // Categorize staff members based on their category field
  const categorizedStaff = {
    leadership: Array.isArray(staffMembers) ? staffMembers.filter(member => 
      member.category?.toLowerCase().includes('director') || 
      member.category?.toLowerCase().includes('leadership') ||
      member.role?.toLowerCase().includes('director')
    ) : [],
    administration: Array.isArray(staffMembers) ? staffMembers.filter(member => 
      member.category?.toLowerCase().includes('administration') ||
      member.category?.toLowerCase().includes('secretary') ||
      member.category?.toLowerCase().includes('finance') ||
      member.category?.toLowerCase().includes('discipline') ||
      member.role?.toLowerCase().includes('secretary') ||
      member.role?.toLowerCase().includes('finance') ||
      member.role?.toLowerCase().includes('administrator')
    ) : [],
    academic: Array.isArray(staffMembers) ? staffMembers.filter(member => 
      member.category?.toLowerCase().includes('academic') ||
      member.category?.toLowerCase().includes('dean') ||
      member.category?.toLowerCase().includes('registrar') ||
      member.role?.toLowerCase().includes('dean') ||
      member.role?.toLowerCase().includes('registrar')
    ) : [],
    support: Array.isArray(staffMembers) ? staffMembers.filter(member => 
      member.category?.toLowerCase().includes('support') ||
      member.category?.toLowerCase().includes('it') ||
      member.category?.toLowerCase().includes('librarian') ||
      member.category?.toLowerCase().includes('technical') ||
      member.role?.toLowerCase().includes('librarian') ||
      member.role?.toLowerCase().includes('it')
    ) : [],
    uncategorized: Array.isArray(staffMembers) ? staffMembers.filter(member => 
      !member.category && !member.role
    ) : []
  };

  // Create categories with counts
  const categories = [
    { 
      id: "all", 
      label: "All Staff", 
      icon: "Users", 
      count: Array.isArray(staffMembers) ? staffMembers.length : 0
    },
    { 
      id: "leadership", 
      label: "Leadership", 
      icon: "Award", 
      count: categorizedStaff.leadership.length 
    },
    { 
      id: "administration", 
      label: "Administration", 
      icon: "Briefcase", 
      count: categorizedStaff.administration.length 
    },
    { 
      id: "academic", 
      label: "Academic", 
      icon: "GraduationCap", 
      count: categorizedStaff.academic.length 
    },
    { 
      id: "support", 
      label: "Support Staff", 
      icon: "Settings", 
      count: categorizedStaff.support.length 
    },
  ];

  // Get filtered staff based on active category
  const getFilteredStaff = () => {
    if (!Array.isArray(staffMembers)) return [];
    
    if (activeCategory === "all") return staffMembers;
    
    if (categorizedStaff[activeCategory]) {
      return categorizedStaff[activeCategory];
    }
    
    return [];
  };

  const filteredStaff = getFilteredStaff();

  const toggleExpanded = (memberId) => {
    setExpandedMember(expandedMember === memberId ? null : memberId);
  };

  // Get director for spotlight section
  const getDirector = () => {
    if (!Array.isArray(staffMembers) || staffMembers.length === 0) return null;
    
    const director = staffMembers.find(member => 
      member.category?.toLowerCase().includes('director') ||
      member.role?.toLowerCase().includes('director')
    );
    
    return director || staffMembers[0];
  };

  const director = getDirector();

  if (loading) {
    return (
      <>
        <Helmet>
          <title>Administration Team - GS DES PARENTS</title>
        </Helmet>
        <PublicHeader />
        <main className="pt-16 min-h-screen bg-gradient-to-b from-background via-background/95 to-background">
          <div className="flex items-center justify-center h-[60vh]">
            <div className="text-center">
              <div className="w-16 h-16 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
              <p className="text-foreground font-medium">Loading staff members...</p>
            </div>
          </div>
        </main>
        <Footer />
      </>
    );
  }

  if (error) {
    return (
      <>
        <Helmet>
          <title>Administration Team - GS DES PARENTS</title>
        </Helmet>
        <PublicHeader />
        <main className="pt-16 min-h-screen bg-gradient-to-b from-background via-background/95 to-background">
          <div className="flex items-center justify-center h-[60vh]">
            <div className="text-center max-w-md">
              <div className="w-16 h-16 rounded-full bg-red-100 flex items-center justify-center mx-auto mb-4">
                <Icon name="AlertCircle" size={32} className="text-red-500" />
              </div>
              <h3 className="font-heading font-bold text-xl text-foreground mb-2">
                Unable to Load Staff
              </h3>
              <p className="text-muted-foreground mb-4">{error}</p>
              <button
                onClick={() => window.location.reload()}
                className="px-6 py-2 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-colors"
              >
                Try Again
              </button>
            </div>
          </div>
        </main>
        <Footer />
      </>
    );
  }

  if (!Array.isArray(staffMembers) || staffMembers.length === 0) {
    return (
      <>
        <Helmet>
          <title>Administration Team - GS DES PARENTS</title>
        </Helmet>
        <PublicHeader />
        <main className="pt-16 min-h-screen bg-gradient-to-b from-background via-background/95 to-background">
          <section className="py-12">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center py-16">
                <div className="w-24 h-24 mx-auto mb-6 rounded-full bg-gray-50 flex items-center justify-center">
                  <Icon name="Users" size={40} className="text-gray-300" />
                </div>
                <h4 className="font-heading font-semibold text-xl text-foreground mb-3">
                  No Staff Members Available
                </h4>
                <p className="font-body text-muted-foreground max-w-md mx-auto mb-6">
                  There are currently no staff members listed in the system.
                </p>
                <button
                  onClick={() => window.location.reload()}
                  className="px-6 py-3 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-colors"
                >
                  Refresh Page
                </button>
              </div>
            </div>
          </section>
        </main>
        <Footer />
      </>
    );
  }

  return (
    <>
      <Helmet>
        <title>Administration Team - GS DES PARENTS</title>
        <meta
          name="description"
          content="Meet the dedicated administration team of GS DES PARENTS - Committed leaders driving educational excellence and student success through visionary leadership."
        />
        <meta
          name="keywords"
          content="GS DES PARENTS administration, school leadership, educational management, administration team, school directors, academic deans"
        />
        <meta
          property="og:title"
          content="Administration Team - GS DES PARENTS"
        />
        <meta
          property="og:description"
          content="Meet our dedicated administration team committed to educational excellence"
        />
        <meta property="og:type" content="website" />
        <meta name="twitter:card" content="summary_large_image" />
        <link rel="canonical" href="/administration" />
      </Helmet>

      <div className="min-h-screen bg-gradient-to-b from-background via-background/95 to-background">
        {/* Header */}
        <PublicHeader />

        {/* Main Content */}
        <main className="pt-16">
          {/* Leadership Spotlight */}
          {director && (
            <section className="py-12">
              <div className="max-w-7xl mx-auto px-4 lg:px-6">
                <div className="bg-gradient-to-r from-primary/5 to-secondary/5 rounded-3xl p-8 lg:p-12">
                  <div className="grid lg:grid-cols-3 gap-8 items-center">
                    <div className="lg:col-span-2">
                      <span className="inline-block px-4 py-2 rounded-full bg-primary text-primary-foreground text-sm font-medium mb-4">
                        Leadership Spotlight
                      </span>
                      <h2 className="font-heading font-bold text-3xl lg:text-4xl text-foreground mb-4">
                        Meet Our Director
                      </h2>
                      <p className="font-body text-lg text-muted-foreground mb-6">
                        Leading with vision and dedication to create an environment where every 
                        student can thrive and achieve their full potential.
                      </p>
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-full bg-primary/10 flex items-center justify-center">
                          <Icon name="Award" size={24} className="text-primary" />
                        </div>
                        <div>
                          <p className="font-heading font-semibold text-foreground">
                            {director.name || "School Director"}
                          </p>
                          <p className="font-body text-primary font-medium">
                            {director.role || director.category || "Director"}
                          </p>
                        </div>
                      </div>
                    </div>
                    
                    {director.image && (
                      <div className="relative">
                        <div className="aspect-square rounded-2xl overflow-hidden shadow-2xl">
                          <Image
                            src={director.image}
                            alt={director.name || "School Director"}
                            className="w-full h-full object-cover"
                            fallbackSrc="../../assets/images/default-avatar.jpg"
                          />
                        </div>
                        <div className="absolute -bottom-4 -right-4 w-24 h-24 bg-primary/10 rounded-2xl -z-10"></div>
                        <div className="absolute -top-4 -left-4 w-20 h-20 bg-secondary/10 rounded-2xl -z-10"></div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </section>
          )}

          {/* Staff Categories Navigation */}
          <section className="py-12">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="mb-10">
                <h3 className="font-heading font-bold text-2xl text-foreground mb-3 text-center">
                  Browse by Department
                </h3>
                <p className="font-body text-muted-foreground text-center max-w-2xl mx-auto">
                  Explore our dedicated teams across different administrative departments
                </p>
              </div>
              
              <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-12">
                {categories.map((category) => (
                  <button
                    key={category.id}
                    onClick={() => setActiveCategory(category.id)}
                    className={`group flex flex-col items-center justify-center p-4 rounded-2xl transition-all duration-300 ${
                      activeCategory === category.id
                        ? "bg-primary text-primary-foreground shadow-lg shadow-primary/25"
                        : "bg-white text-foreground shadow-md hover:shadow-lg hover:bg-primary/5 border border-gray-100"
                    }`}
                  >
                    <div className={`w-12 h-12 rounded-xl flex items-center justify-center mb-3 transition-colors ${
                      activeCategory === category.id
                        ? "bg-white/20"
                        : "bg-primary/10 text-primary group-hover:bg-primary/20"
                    }`}>
                      <Icon name={category.icon} size={24} />
                    </div>
                    <span className="font-body font-medium text-sm mb-1">
                      {category.label}
                    </span>
                    <span className={`text-xs px-2 py-1 rounded-full ${
                      activeCategory === category.id
                        ? "bg-white/20"
                        : "bg-gray-100 text-gray-600"
                    }`}>
                      {category.count} members
                    </span>
                  </button>
                ))}
              </div>

              {/* Staff Grid */}
              <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {filteredStaff.map((member) => (
                  <div
                    key={member.uniqueId}
                    className={`group bg-card border border-gray-200 rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-500 hover:-translate-y-2 ${
                      expandedMember === member.uniqueId ? "ring-2 ring-primary/20" : ""
                    }`}
                    onClick={() => toggleExpanded(member.uniqueId)}
                  >
                    {/* Member Header */}
                    <div className="relative overflow-hidden h-48">
                      {member.image ? (
                        <Image
                          src={member.image}
                          alt={member.name || "Staff Member"}
                          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                          fallbackSrc="../../assets/images/default-avatar.jpg"
                        />
                      ) : (
                        <div className="w-full h-full bg-gradient-to-br from-primary/20 to-secondary/20 flex items-center justify-center">
                          <Icon name="User" size={48} className="text-primary/50" />
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent"></div>
                      
                      {/* Category Badge */}
                      <div className="absolute top-4 left-4">
                        <span className="px-3 py-1 bg-white/90 backdrop-blur-sm text-foreground rounded-full text-xs font-medium">
                          {member.category || member.profession || member.role || "Staff Member"}
                        </span>
                      </div>
                      
                      {/* View Details Button */}
                      <div className="absolute top-4 right-4">
                        <button className="w-8 h-8 bg-white/90 backdrop-blur-sm rounded-full flex items-center justify-center text-foreground hover:bg-white transition-colors">
                          <Icon 
                            name={expandedMember === member.uniqueId ? "Minus" : "Plus"} 
                            size={16} 
                          />
                        </button>
                      </div>
                    </div>

                    {/* Member Info */}
                    <div className="p-6">
                      <h3 className="font-heading font-semibold text-xl text-foreground mb-1 line-clamp-1">
                        {member.name || "Staff Member"}
                      </h3>
                      <p className="font-body text-primary font-medium mb-3">
                        {member.role || member.category || "Administrative Staff"}
                      </p>
                      {member.profession && (
                        <p className="font-body text-sm text-muted-foreground mb-4 line-clamp-2">
                          {member.profession}
                        </p>
                      )}

                      {/* Expanded Details */}
                      {expandedMember === member.uniqueId && (
                        <div className="mt-6 pt-6 border-t border-gray-100 animate-in fade-in">
                          <div className="space-y-4">
                            {/* Contact Info */}
                            <div className="grid grid-cols-2 gap-4">
                              {member.social?.email && (
                                <div>
                                  <h4 className="font-body font-medium text-foreground mb-2 flex items-center">
                                    <Icon name="Mail" size={14} className="mr-2 text-primary" />
                                    Email
                                  </h4>
                                  <a
                                    href={`mailto:${member.social.email}`}
                                    className="font-body text-sm text-muted-foreground hover:text-primary transition-colors break-all"
                                  >
                                    {member.social.email}
                                  </a>
                                </div>
                              )}
                              {member.phone && (
                                <div>
                                  <h4 className="font-body font-medium text-foreground mb-2 flex items-center">
                                    <Icon name="Phone" size={14} className="mr-2 text-primary" />
                                    Phone
                                  </h4>
                                  <a
                                    href={`tel:${member.phone}`}
                                    className="font-body text-sm text-muted-foreground hover:text-primary transition-colors"
                                  >
                                    {member.phone}
                                  </a>
                                </div>
                              )}
                            </div>

                            {/* Profession Details */}
                            {member.profession && (
                              <div>
                                <h4 className="font-body font-medium text-foreground mb-2 flex items-center">
                                  <Icon name="Briefcase" size={14} className="mr-2 text-primary" />
                                  Profession
                                </h4>
                                <p className="font-body text-sm text-muted-foreground">
                                  {member.profession}
                                </p>
                              </div>
                            )}

                            {/* Category */}
                            {(member.category || member.role) && (
                              <div>
                                <h4 className="font-body font-medium text-foreground mb-2 flex items-center">
                                  <Icon name="Tag" size={14} className="mr-2 text-primary" />
                                  {member.category ? "Department" : "Role"}
                                </h4>
                                <p className="font-body text-sm text-muted-foreground">
                                  {member.category || member.role}
                                </p>
                              </div>
                            )}
                          </div>
                        </div>
                      )}

                      {/* Social Links */}
                      <div className="flex items-center justify-between mt-4">
                        <div className="flex items-center space-x-2">
                          {member.social?.email && (
                            <a
                              href={`mailto:${member.social.email}`}
                              className="w-9 h-9 bg-primary/10 hover:bg-primary text-primary hover:text-primary-foreground rounded-lg flex items-center justify-center transition-all duration-300 hover:scale-105"
                              aria-label={`Email ${member.name || "staff member"}`}
                            >
                              <Icon name="Mail" size={16} />
                            </a>
                          )}
                          {member.social?.linkedin && member.social.linkedin !== "#" && (
                            <a
                              href={member.social.linkedin}
                              className="w-9 h-9 bg-primary/10 hover:bg-primary text-primary hover:text-primary-foreground rounded-lg flex items-center justify-center transition-all duration-300 hover:scale-105"
                              aria-label={`${member.name || "staff member"} LinkedIn`}
                              target="_blank"
                              rel="noopener noreferrer"
                            >
                              <Icon name="Linkedin" size={16} />
                            </a>
                          )}
                        </div>
                        
                        <div className="flex items-center text-sm text-muted-foreground">
                          <Icon name="Clock" size={14} className="mr-1" />
                          <span>Click for details</span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Empty State for filtered results */}
              {filteredStaff.length === 0 && !loading && (
                <div className="text-center py-16">
                  <div className="w-24 h-24 mx-auto mb-6 rounded-full bg-gray-50 flex items-center justify-center">
                    <Icon name="Users" size={40} className="text-gray-300" />
                  </div>
                  <h4 className="font-heading font-semibold text-xl text-foreground mb-3">
                    No staff members found in this category
                  </h4>
                  <p className="font-body text-muted-foreground max-w-md mx-auto mb-4">
                    No staff members are currently listed in this category. Please select a different category.
                  </p>
                  <button
                    onClick={() => setActiveCategory("all")}
                    className="px-6 py-2 bg-primary text-primary-foreground rounded-lg font-medium hover:bg-primary/90 transition-colors"
                  >
                    View All Staff
                  </button>
                </div>
              )}
            </div>
          </section>

          {/* Team Structure Overview */}
          <section className="py-16 bg-gray-50/50">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h2 className="font-heading font-bold text-3xl text-foreground mb-4">
                  Our Administrative Structure
                </h2>
                <p className="font-body text-lg text-muted-foreground max-w-2xl mx-auto">
                  A well-organized team structure ensuring efficient school management
                </p>
              </div>

              <div className="grid md:grid-cols-4 gap-6">
                {categories.slice(1).map((category) => (
                  <div key={category.id} className="bg-white rounded-2xl p-6 shadow-lg border border-gray-100">
                    <div className={`w-12 h-12 rounded-xl ${
                      category.id === 'leadership' ? 'bg-primary/10' :
                      category.id === 'administration' ? 'bg-secondary/10' :
                      category.id === 'academic' ? 'bg-green-500/10' :
                      'bg-purple-500/10'
                    } flex items-center justify-center mb-4`}>
                      <Icon 
                        name={category.icon} 
                        size={24} 
                        className={
                          category.id === 'leadership' ? 'text-primary' :
                          category.id === 'administration' ? 'text-secondary' :
                          category.id === 'academic' ? 'text-green-500' :
                          'text-purple-500'
                        } 
                      />
                    </div>
                    <h3 className="font-heading font-semibold text-lg text-foreground mb-2">
                      {category.label}
                    </h3>
                    <p className="font-body text-sm text-muted-foreground mb-4">
                      {category.id === 'leadership' ? 'Visionary leaders setting strategic direction' :
                       category.id === 'administration' ? 'Dedicated professionals managing daily operations' :
                       category.id === 'academic' ? 'Experts supporting academic excellence' :
                       'Essential personnel ensuring smooth operations'}
                    </p>
                    <div className="pt-4 border-t border-gray-100">
                      <span className="text-2xl font-bold text-foreground">
                        {category.count}
                      </span>
                      <span className="text-sm text-muted-foreground ml-2">Members</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </section>

          {/* Contact CTA */}
          <section className="py-16">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="bg-gradient-to-r from-primary to-secondary rounded-3xl p-8 lg:p-12 text-center">
                <div className="max-w-2xl mx-auto">
                  <h2 className="font-heading font-bold text-3xl text-white mb-4">
                    Need to Contact Our Administration?
                  </h2>
                  <p className="font-body text-white/90 mb-8">
                    Our administration team is here to assist you with inquiries, 
                    support, and guidance. Reach out to us for any assistance.
                  </p>
                  <div className="flex flex-col sm:flex-row gap-4 justify-center">
                    <a
                      href="mailto:info@unmuterwanda.org"
                      className="inline-flex items-center justify-center px-6 py-3 bg-white text-primary rounded-lg font-medium hover:bg-white/90 transition-colors"
                    >
                      <Icon name="Mail" size={18} className="mr-2" />
                      Email Administration
                    </a>
                    <a
                      href="/contact"
                      className="inline-flex items-center justify-center px-6 py-3 bg-transparent border-2 border-white text-white rounded-lg font-medium hover:bg-white/10 transition-colors"
                    >
                      <Icon name="Phone" size={18} className="mr-2" />
                      Call Our Office
                    </a>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </main>

        {/* Footer - The duplicate key warning might be coming from here */}
        <Footer />
      </div>
    </>
  );
};

export default AdministrationMenu;