import React, { useState, useEffect } from "react";
import Icon from "../../components/AppIcon";
import { Helmet } from "react-helmet";
import PublicHeader from "../../components/ui/PublicHeader";
import Footer from "../../components/ui/Footer";

const Notifications = () => {
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filterType, setFilterType] = useState("all");
  const [searchTerm, setSearchTerm] = useState("");
  const [showNotification, setShowNotification] = useState(null);

  // Notification types matching your Mongoose model
  const notificationTypes = [
    { id: "all", name: "All Notifications", icon: "Bell", color: "text-gray-600", bgColor: "bg-gray-100" },
    { id: "info", name: "Information", icon: "Info", color: "text-blue-600", bgColor: "bg-blue-100" },
    { id: "success", name: "Success", icon: "CheckCircle", color: "text-green-600", bgColor: "bg-green-100" },
    { id: "warning", name: "Warnings", icon: "AlertTriangle", color: "text-yellow-600", bgColor: "bg-yellow-100" },
    { id: "error", name: "Important", icon: "AlertCircle", color: "text-red-600", bgColor: "bg-red-100" },
  ];

  // Fetch notifications from API using fetch
  useEffect(() => {
    const fetchNotifications = async () => {
      try {
        setLoading(true);
        const response = await fetch("https://new-school-web-90vd.onrender.com/notification");
        
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        
        const data = await response.json();
        
        // Handle different response structures
        let notificationsData = [];
        if (Array.isArray(data)) {
          notificationsData = data;
        } else if (data && Array.isArray(data.notifications)) {
          notificationsData = data.notifications;
        } else if (data && Array.isArray(data.data)) {
          notificationsData = data.data;
        } else {
          console.warn("Unexpected API response structure:", data);
        }
        
        // Transform notifications to ensure they have required fields
        const transformedNotifications = notificationsData.map(notification => ({
          id: notification.id || notification._id,
          title: notification.title || "Untitled Notification",
          message: notification.message || "No message available",
          type: notification.type || "info",
          timestamp: notification.timestamp || notification.createdAt || new Date().toISOString(),
          createdAt: notification.createdAt || new Date().toISOString(),
          updatedAt: notification.updatedAt || new Date().toISOString()
        })).sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp)); // Sort by latest
        
        setNotifications(transformedNotifications);
        setError(null);
      } catch (err) {
        console.error("Error fetching notifications:", err);
        setError("Failed to load notifications. Please try again later.");
        setNotifications([]);
      } finally {
        setLoading(false);
      }
    };

    fetchNotifications();
    
    // Refresh notifications every 30 seconds
    const intervalId = setInterval(fetchNotifications, 30000);
    
    return () => clearInterval(intervalId);
  }, []);

  // Filter notifications based on search and type
  const filteredNotifications = notifications.filter((notification) => {
    const matchesSearch =
      notification.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
      notification.message.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesType = filterType === "all" || notification.type === filterType;
    return matchesSearch && matchesType;
  });

  // Group notifications by date
  const groupedNotifications = filteredNotifications.reduce((groups, notification) => {
    const date = new Date(notification.timestamp);
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    
    let groupKey;
    if (date.toDateString() === today.toDateString()) {
      groupKey = "Today";
    } else if (date.toDateString() === yesterday.toDateString()) {
      groupKey = "Yesterday";
    } else {
      groupKey = date.toLocaleDateString("en-US", {
        weekday: "long",
        year: "numeric",
        month: "long",
        day: "numeric"
      });
    }
    
    if (!groups[groupKey]) {
      groups[groupKey] = [];
    }
    groups[groupKey].push(notification);
    return groups;
  }, {});

  // Get notification type details
  const getNotificationType = (type) => {
    return notificationTypes.find(nt => nt.id === type) || notificationTypes[0];
  };

  // Format timestamp
  const formatTimestamp = (timestamp) => {
    if (!timestamp) return "Just now";
    
    const date = new Date(timestamp);
    const now = new Date();
    const diffInMinutes = Math.floor((now - date) / (1000 * 60));
    
    if (diffInMinutes < 1) return "Just now";
    if (diffInMinutes < 60) return `${diffInMinutes}m ago`;
    if (diffInMinutes < 1440) return `${Math.floor(diffInMinutes / 60)}h ago`;
    
    return date.toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit"
    });
  };

  // Format detailed date
  const formatDetailedDate = (timestamp) => {
    if (!timestamp) return "";
    
    const date = new Date(timestamp);
    return date.toLocaleDateString("en-US", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit"
    });
  };

  // Get notification count by type
  const getNotificationCount = (type) => {
    if (type === "all") return notifications.length;
    return notifications.filter(n => n.type === type).length;
  };

  // Mark all as read (simulated)
  const handleMarkAllAsRead = () => {
    alert("All notifications marked as read!");
    // In a real app, you would update the backend
  };

  // Clear all notifications (simulated)
  const handleClearAll = () => {
    if (window.confirm("Are you sure you want to clear all notifications?")) {
      alert("All notifications cleared!");
      // In a real app, you would update the backend
    }
  };

  // Show notification details
  const handleShowNotification = (notification) => {
    setShowNotification(notification);
  };

  return (
    <>
      <Helmet>
        <title>Notifications - GS DES PARENTS</title>
        <meta
          name="description"
          content="Stay updated with the latest school announcements, alerts, and important information from GS DES PARENTS."
        />
        <meta
          name="keywords"
          content="notifications, alerts, announcements, school updates, GS DES PARENTS, important information"
        />
        <meta property="og:title" content="Notifications - GS DES PARENTS" />
        <meta
          property="og:description"
          content="Stay updated with the latest school announcements and alerts"
        />
        <meta property="og:type" content="website" />
        <meta name="twitter:card" content="summary_large_image" />
        <link rel="canonical" href="/notifications" />
      </Helmet>

      <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white">
        {/* Header */}
        <PublicHeader />

        {/* Main Content */}
        <main className="pt-16">
          {/* Hero Section with Gradient */}
          <section className="relative py-16 lg:py-20 bg-gradient-to-r from-blue-600 via-purple-600 to-indigo-600">
            <div className="absolute inset-0 bg-black/10" />
            <div className="relative max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h1 className="font-heading font-bold text-4xl lg:text-5xl text-white mb-4 drop-shadow-lg">
                  Notifications Center
                </h1>
                <p className="font-body text-lg text-blue-100 max-w-3xl mx-auto">
                  Stay updated with the latest school announcements, alerts, and important information.
                  Never miss an important update from GS DES PARENTS.
                </p>
              </div>

              {/* Stats Overview */}
              <div className="max-w-5xl mx-auto">
                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                  {notificationTypes.map((type) => (
                    <div
                      key={type.id}
                      onClick={() => setFilterType(type.id)}
                      className={`bg-white/20 backdrop-blur-sm rounded-xl p-4 text-center cursor-pointer transition-all duration-300 hover:bg-white/30 hover:scale-105 ${
                        filterType === type.id ? 'ring-2 ring-white' : ''
                      }`}
                    >
                      <div className="flex flex-col items-center">
                        <Icon name={type.icon} size={24} className="text-white mb-2" />
                        <div className="text-white font-semibold">{getNotificationCount(type.id)}</div>
                        <div className="text-blue-100 text-xs mt-1">{type.name}</div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </section>

          {/* Notifications Content */}
          <section className="py-16 lg:py-20">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              {/* Header with Controls */}
              <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between mb-8 gap-4">
                <div className="flex items-center space-x-4">
                  <h2 className="font-heading font-semibold text-2xl lg:text-3xl text-gray-900">
                    Notifications ({filteredNotifications.length})
                  </h2>
                  {filterType !== "all" && (
                    <span className={`px-4 py-1 ${getNotificationType(filterType).bgColor} ${getNotificationType(filterType).color} rounded-full text-sm font-medium border border-current/20`}>
                      {getNotificationType(filterType).name}
                    </span>
                  )}
                </div>
                
                <div className="flex flex-wrap items-center gap-2">
                  {/* Search Input */}
                  <div className="relative">
                    <Icon
                      name="Search"
                      size={18}
                      className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"
                    />
                    <input
                      type="text"
                      placeholder="Search notifications..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent shadow-sm w-48"
                    />
                  </div>
                  
                  {/* Action Buttons */}
                  <div className="flex gap-2">
                    <button
                      onClick={handleMarkAllAsRead}
                      className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center space-x-2"
                    >
                      <Icon name="CheckCircle" size={16} />
                      <span className="hidden sm:inline">Mark All Read</span>
                    </button>
                    <button
                      onClick={handleClearAll}
                      className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors flex items-center space-x-2"
                    >
                      <Icon name="Trash2" size={16} />
                      <span className="hidden sm:inline">Clear All</span>
                    </button>
                  </div>
                </div>
              </div>

              {/* Loading State */}
              {loading && (
                <div className="flex flex-col items-center justify-center py-20">
                  <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div>
                  <p className="text-gray-600">Loading notifications...</p>
                </div>
              )}

              {/* Error State */}
              {error && !loading && (
                <div className="bg-red-50 border border-red-200 rounded-2xl p-8 text-center my-8">
                  <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icon name="AlertCircle" size={32} className="text-red-600" />
                  </div>
                  <h3 className="font-heading font-semibold text-xl text-red-800 mb-2">
                    Unable to Load Notifications
                  </h3>
                  <p className="text-red-600 mb-4">{error}</p>
                  <button
                    onClick={() => window.location.reload()}
                    className="px-6 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                  >
                    Retry
                  </button>
                </div>
              )}

              {/* Notifications Content */}
              {!loading && !error && (
                <>
                  {filteredNotifications.length > 0 ? (
                    <div className="space-y-8">
                      {Object.entries(groupedNotifications).map(([date, notifications]) => (
                        <div key={date} className="space-y-4">
                          <div className="flex items-center space-x-2">
                            <div className="h-px flex-1 bg-gray-200"></div>
                            <span className="font-semibold text-gray-500 px-4">{date}</span>
                            <div className="h-px flex-1 bg-gray-200"></div>
                          </div>
                          
                          <div className="space-y-3">
                            {notifications.map((notification) => {
                              const type = getNotificationType(notification.type);
                              return (
                                <div
                                  key={notification.id}
                                  className={`bg-white border border-gray-200 rounded-xl p-5 shadow-sm hover:shadow-md transition-all duration-300 hover:border-${type.color.split('-')[1]}-200 hover:-translate-y-1 cursor-pointer`}
                                  onClick={() => handleShowNotification(notification)}
                                >
                                  <div className="flex items-start justify-between">
                                    <div className="flex items-start space-x-4 flex-1">
                                      {/* Notification Icon */}
                                      <div className={`w-12 h-12 ${type.bgColor} rounded-xl flex items-center justify-center`}>
                                        <Icon
                                          name={type.icon}
                                          size={24}
                                          className={type.color}
                                        />
                                      </div>
                                      
                                      {/* Notification Content */}
                                      <div className="flex-1 min-w-0">
                                        <div className="flex items-center justify-between mb-1">
                                          <h3 className="font-heading font-semibold text-lg text-gray-900 truncate">
                                            {notification.title}
                                          </h3>
                                          <span className="text-xs text-gray-500 whitespace-nowrap ml-2">
                                            {formatTimestamp(notification.timestamp)}
                                          </span>
                                        </div>
                                        
                                        <p className="text-gray-600 line-clamp-2 mb-3">
                                          {notification.message}
                                        </p>
                                        
                                        <div className="flex items-center justify-between">
                                          <span className={`text-xs font-medium px-2 py-1 ${type.bgColor} ${type.color} rounded-full`}>
                                            {type.name}
                                          </span>
                                          <button
                                            onClick={(e) => {
                                              e.stopPropagation();
                                              handleShowNotification(notification);
                                            }}
                                            className="text-blue-600 hover:text-blue-700 text-sm font-medium flex items-center space-x-1"
                                          >
                                            <span>View Details</span>
                                            <Icon name="ChevronRight" size={14} />
                                          </button>
                                        </div>
                                      </div>
                                    </div>
                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    // Empty State
                    <div className="text-center py-16 bg-gradient-to-b from-gray-50 to-white rounded-2xl border border-gray-200">
                      <div className="w-24 h-24 bg-gradient-to-br from-gray-100 to-gray-200 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Icon
                          name="BellOff"
                          size={48}
                          className="text-gray-400"
                        />
                      </div>
                      <h3 className="font-heading font-semibold text-xl text-gray-900 mb-2">
                        No notifications found
                      </h3>
                      <p className="text-gray-600 mb-6 max-w-md mx-auto">
                        {searchTerm || filterType !== "all" 
                          ? "Try adjusting your search terms or filter" 
                          : "You're all caught up! No new notifications."}
                      </p>
                      {(searchTerm || filterType !== "all") && (
                        <button
                          onClick={() => {
                            setSearchTerm("");
                            setFilterType("all");
                          }}
                          className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                        >
                          Clear Filters
                        </button>
                      )}
                    </div>
                  )}
                </>
              )}
            </div>
          </section>

          {/* Notification Types Quick Filter */}
          <section className="py-16 lg:py-20 bg-gradient-to-b from-gray-50 to-white">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <div className="text-center mb-12">
                <h2 className="font-heading font-bold text-3xl lg:text-4xl text-gray-900 mb-4">
                  Filter by Notification Type
                </h2>
                <p className="font-body text-lg text-gray-600 max-w-2xl mx-auto">
                  Quickly find notifications by their type and importance level
                </p>
              </div>

              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
                {notificationTypes.slice(1).map((type) => {
                  const count = getNotificationCount(type.id);
                  return (
                    <div
                      key={type.id}
                      onClick={() => setFilterType(type.id)}
                      className={`group bg-white border border-gray-200 rounded-2xl p-6 text-center hover:shadow-xl transition-all duration-300 cursor-pointer hover:border-${type.color.split('-')[1]}-200 relative overflow-hidden ${
                        filterType === type.id ? 'ring-2 ring-blue-500' : ''
                      }`}
                    >
                      <div className="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-gray-200 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                      <div className={`w-16 h-16 ${type.bgColor} rounded-2xl flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform`}>
                        <Icon
                          name={type.icon}
                          size={32}
                          className={type.color}
                        />
                      </div>
                      <h3 className="font-heading font-semibold text-lg text-gray-900 mb-2">
                        {type.name}
                      </h3>
                      <p className="text-sm text-gray-600 mb-2">
                        {count} notification{count !== 1 ? 's' : ''}
                      </p>
                      <div className="mt-4 pt-4 border-t border-gray-100">
                        <span className={`text-sm font-medium ${type.color} flex items-center justify-center space-x-1`}>
                          <Icon name="Filter" size={14} />
                          <span>Filter by {type.name}</span>
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>
        </main>

        {/* Notification Detail Modal */}
        {showNotification && (
          <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-hidden">
              {/* Modal Header */}
              <div className={`p-6 ${getNotificationType(showNotification.type).bgColor} border-b border-gray-200`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center space-x-3">
                    <div className={`w-10 h-10 ${getNotificationType(showNotification.type).bgColor} rounded-lg flex items-center justify-center`}>
                      <Icon
                        name={getNotificationType(showNotification.type).icon}
                        size={20}
                        className={getNotificationType(showNotification.type).color}
                      />
                    </div>
                    <h3 className="font-heading font-semibold text-xl text-gray-900">
                      {showNotification.title}
                    </h3>
                  </div>
                  <button
                    onClick={() => setShowNotification(null)}
                    className="text-gray-400 hover:text-gray-600"
                  >
                    <Icon name="X" size={24} />
                  </button>
                </div>
                <div className="flex items-center space-x-4 mt-3">
                  <span className={`text-sm font-medium px-3 py-1 ${getNotificationType(showNotification.type).bgColor} ${getNotificationType(showNotification.type).color} rounded-full`}>
                    {getNotificationType(showNotification.type).name}
                  </span>
                  <span className="text-sm text-gray-500">
                    {formatDetailedDate(showNotification.timestamp)}
                  </span>
                </div>
              </div>
              
              {/* Modal Body */}
              <div className="p-6 overflow-y-auto max-h-[60vh]">
                <div className="prose prose-lg max-w-none">
                  <p className="text-gray-700 whitespace-pre-wrap">
                    {showNotification.message}
                  </p>
                </div>
              </div>
              
              {/* Modal Footer */}
              <div className="p-6 border-t border-gray-200">
                <div className="flex justify-end space-x-3">
                  <button
                    onClick={() => {
                      // Handle notification action here
                      alert(`Action taken for: ${showNotification.title}`);
                      setShowNotification(null);
                    }}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                  >
                    Take Action
                  </button>
                  <button
                    onClick={() => setShowNotification(null)}
                    className="px-6 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Footer */}
        <Footer />
      </div>
    </>
  );
};

export default Notifications;