import React from "react";
import { BrowserRouter, Routes as RouterRoutes, Route } from "react-router-dom";
import ScrollToTop from "components/ScrollToTop";
import ErrorBoundary from "components/ErrorBoundary";
import NotFound from "pages/NotFound";
import PublicHomepage from "./pages/public-homepage";
import PublicEvent from "pages/public-homepage/events";
import PublicContact from "pages/public-homepage/contact";
import AboutUs from "./pages/about-us";
import AdminstrationMenu from "./pages/Menu/Adminstration"
import BlogListing from "./pages/blog-listing";
import BlogPostView from "./pages/blog-post-view";
import LibraryContent from "pages/Menu/Library";
import Gallery from "pages/Gallery";
import SchoolApplication from "pages/apply";
import Documents from "pages/Menu/Documents";
import Notification from "pages/Menu/Notification";

const Routes = () => {
  return (
    <BrowserRouter>
      <ErrorBoundary>
        <ScrollToTop />
        <RouterRoutes>
          {/* Define your route here */}
          <Route path="/" element={<PublicHomepage />} />
          <Route path="/apply" element={<SchoolApplication />} />
          <Route path="/about-us" element={<AboutUs />} />
          <Route path="/gallery" element={<Gallery />} />
          <Route path="/contact" element={<PublicContact />} />
          <Route path="/administration" element={<AdminstrationMenu />} />
          <Route path="/documents" element={<Documents />} />
          <Route path="/notification" element={<Notification />} />
          <Route path="/library" element={<LibraryContent />} />
          <Route path="/events" element={<PublicEvent />} />
          <Route path="/blog-listing" element={<BlogListing />} />
          <Route path="/blog-post-view" element={<BlogPostView />} />
          <Route path="*" element={<NotFound />} />
        </RouterRoutes>
      </ErrorBoundary>
    </BrowserRouter>
  );
};

export default Routes;
