const BlogPostView = () => {
  const [searchParams] = useSearchParams();
  const [readingProgress, setReadingProgress] = useState(0);
  const [isBookmarked, setIsBookmarked] = useState(false);

  const postSlug =
    searchParams?.get("slug") ;

  // In a real app, you would fetch the post based on the slug
  const post = mockBlogPost;

  // Calculate reading progress
  useEffect(() => {
    const handleScroll = () => {
      const article = document.querySelector("[data-article-content]");
      if (article) {
        const rect = article?.getBoundingClientRect();
        const windowHeight = window.innerHeight;
        const documentHeight = article?.offsetHeight;

        const scrolled = Math.max(0, windowHeight - rect?.top);
        const progress = Math.min(100, (scrolled / documentHeight) * 100);

        setReadingProgress(progress);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const handleShare = (platform) => {
    const url = `${window?.location?.origin}/blog-post-view?slug=${post?.slug}`;
    const title = post?.title;

    const shareUrls = {
      twitter: `https://twitter.com/intent/tweet?text=${encodeURIComponent(
        title
      )}&url=${encodeURIComponent(url)}`,
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(
        url
      )}`,
      linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(
        url
      )}`,
    };

    if (shareUrls?.[platform]) {
      window?.open(shareUrls?.[platform], "_blank", "width=600,height=400");
    }
  };



  const toggleBookmark = () => {
    setIsBookmarked(!isBookmarked);
    // In a real app, this would save to user's bookmarks
  };

  if (!post) {
    return (
      <div className="min-h-screen bg-background">
        <PublicHeader />
        <main className="pt-16">
          <div className="max-w-4xl mx-auto px-4 lg:px-6 py-12 text-center">
            <h1 className="font-heading font-bold text-2xl text-foreground mb-4">
              Book  Not Found
            </h1>
            <p className="font-body text-muted-foreground mb-6">
              The book you're looking for doesn't exist or has been moved.
            </p>
            <Link
              to="/library"
              className="inline-flex items-center text-primary hover:text-primary/80 font-body font-medium"
            >
              ← Back to Library
            </Link>
          </div>
        </main>
      </div>
    );
  }

  return (
    <>
      <Helmet>
        <title>{post?.title} - GS DES PARENTS </title>
        <meta name="description" content={post?.excerpt} />
        <meta
          name="keywords"
          content={
            post?.tags?.join(", ") + ", CEFOTEC, GSPHUYE, GS DES PARENTS"
          }
        />
        <meta name="author" content={post?.author?.name} />
        <meta property="article:published_time" content={post?.publishedDate} />
        <meta property="article:modified_time" content={post?.lastModified} />
        <meta property="article:author" content={post?.author?.name} />
        <meta property="article:section" content={post?.category} />
        <meta
          property="article:tag"
          content={
            post?.tags?.join(", ") + ", CEFOTEC, GSPHUYE, GS DES PARENTS"
          }
        />
        <meta property="og:title" content={post?.title + " | GS DES PARENTS"} />
        <meta property="og:description" content={post?.excerpt} />
        <meta property="og:type" content="article" />
        <meta property="og:image" content={post?.featuredImage} />
        <link rel="canonical" href={`/blog-post-view?slug=${post?.slug}`} />
      </Helmet>

      <div className="min-h-screen bg-background">
        {/* Reading Progress Bar */}
        <div
          className="fixed top-0 left-0 h-1 bg-primary z-50 transition-all duration-150"
          style={{ width: `${readingProgress}%` }}
        />

        <PublicHeader />

        <main className="pt-16">
          {/* Breadcrumb Navigation */}
          <div className="bg-muted/30 py-4">
            <div className="max-w-7xl mx-auto px-4 lg:px-6">
              <BreadcrumbNavigation />
              <nav className="mt-2" aria-label="Breadcrumb">
                <ol className="flex items-center space-x-2 text-sm">
                  <li>
                    <Link
                      to="/public-homepage"
                      className="text-muted-foreground hover:text-primary transition-smooth"
                    >
                      Home
                    </Link>
                  </li>
                  <li className="text-muted-foreground">/</li>
                  <li>
                    <Link
                      to="/blog-listing"
                      className="text-muted-foreground hover:text-primary transition-smooth"
                    >
                      Library
                    </Link>
                  </li>
                  <li className="text-muted-foreground">/</li>
                  <li className="text-foreground font-medium truncate">
                    {post?.title}
                  </li>
                </ol>
              </nav>
            </div>
          </div>

          {/* Article Layout */}
          <div className="max-w-7xl mx-auto px-4 lg:px-6 py-8">
            <div className="lg:grid lg:grid-cols-12 lg:gap-8">
              {/* Main Article Content */}
              <div className="lg:col-span-8">
                <article className="bg-card rounded-lg border border-border shadow-card overflow-hidden">
                  <ArticleHeader
                    post={post}
                  />

                </article>

              </div>

              {/* Sidebar */}
              <div className="lg:col-span-4 mt-8 lg:mt-0 sm:mt-1">
                <ArticleSidebar
                  post={post}
                  onShare={handleShare}
                  onBookmark={toggleBookmark}
                  isBookmarked={isBookmarked}
                />
              </div>
            </div>
          </div>
        </main>

        {/* Footer */}
        <Footer/>
      </div>
    </>
  );
};

export default BlogPostView;
